        IEnumerator ProductionScenario(bool cached){
            // Equivalent CPU-only reproduction of four completed, army-blocked
            // producers against 855 static building footprints. Army occupancy is
            // assumed blocked in both cases; GPU cost is deliberately not modeled.
            const int frames=120,buildings=855;var points=new Vector3[buildings];for(int i=0;i<points.Length;i++)points[i]=new Vector3((i%29)*.00001f,.1f,(i/29)*.00001f).normalized;
            var candidates=new Vector3[96];for(int i=0;i<96;i++)candidates[i]=new Vector3(1,i*.00001f,0).normalized;
            var states=new ProductionExitState[4];for(int i=0;i<4;i++){states[i]=new ProductionExitState{search=96};states[i].sites.AddRange(candidates);states[i].Sleep(0,0);}
            var samples=new List<double>();var timer=Stopwatch.StartNew();var cpu=new Stopwatch();int staticChecks=0;
            for(int frame=0;frame<frames;frame++){cpu.Restart();for(int producer=0;producer<4;producer++)if(cached){if(states[producer].CanWake(frame/60.0,0))states[producer].Sleep(frame/60.0,0);}else foreach(var point in candidates)foreach(var other in points){if(CubeSphere.ArcDistance(point,other,120000)<20)throw new InvalidOperationException("Fixture footprint unexpectedly overlaps an exit");staticChecks++;}samples.Add(cpu.Elapsed.TotalMilliseconds);yield return null;}
            samples.Sort();GetProcessMemoryInfo(GetCurrentProcess(),out var memory,(uint)Marshal.SizeOf<Memory>());report.productionResults.Add(new Result{scheduler=cached?"cached blocked exits":"previous full exit search",plots=buildings,frames=frames,medianMs=samples[frames/2],p95Ms=samples[(int)Math.Ceiling(frames*.95)-1],updatesPerSecond=frames/timer.Elapsed.TotalSeconds,allocatedBytes=Profiler.GetTotalAllocatedMemoryLong(),reservedBytes=Profiler.GetTotalReservedMemoryLong(),workingSetBytes=(long)memory.workingSet.ToUInt64(),privateBytes=(long)memory.privateBytes.ToUInt64()});
            Check(cached?staticChecks==0:staticChecks==frames*4*96*buildings,cached?"Sleeping producers repeat no static footprint searches":"CPU baseline repeats the original blocked-production footprint workload");
        }
        IEnumerator WorkforceScenario(PlanetRtsBase local,ColonyState colony,bool revised){
            const int frames=1600;var samples=new List<double>();var elapsed=Stopwatch.StartNew();var cpu=new Stopwatch();
            for(int frame=0;frame<frames;frame++){cpu.Restart();if(revised)CivilisationRuntime.AllocateWorkers(local,colony,0,false);else Baseline();samples.Add(cpu.Elapsed.TotalMilliseconds);yield return null;}
            samples.Sort();GetProcessMemoryInfo(GetCurrentProcess(),out var memory,(uint)Marshal.SizeOf<Memory>());report.workforceResults.Add(new Result{scheduler=revised?"recovery priorities":"previous priorities",plots=local.Buildings.Count,frames=frames,medianMs=samples[frames/2],p95Ms=samples[(int)Math.Ceiling(frames*.95)-1],updatesPerSecond=frames/elapsed.Elapsed.TotalSeconds,allocatedBytes=Profiler.GetTotalAllocatedMemoryLong(),reservedBytes=Profiler.GetTotalReservedMemoryLong(),workingSetBytes=(long)memory.workingSet.ToUInt64(),privateBytes=(long)memory.privateBytes.ToUInt64()});
            // Saved pre-fix allocation policy, on the same infrastructure fixture.
            void Baseline(){colony.workforce=Math.Max(0,Math.Min(colony.population,colony.residents.Count==0?colony.population:colony.workforce));colony.employed=colony.workerDemand=colony.plannedWorkerDemand=0;
                foreach(var b in local.Buildings){if(b.team!=0||b.removed)continue;b.WorkersAssigned=0;b.WorkforceEfficiency=b.definition.workers==0?1:0;if(b.paused||!b.powered||b.roadSuspended||b.node>=0&&local.Nodes[b.node].remaining<=0)continue;int required=b.definition.workers*b.level;colony.plannedWorkerDemand+=required;if(b.Complete)colony.workerDemand+=required;}
                int projects=0;foreach(var b in local.Buildings)if(b.team==0&&!b.removed&&!b.paused&&!b.roadSuspended&&b.powered&&!b.awaitingProjectMaterials&&(!b.Complete||b.repairing&&b.health<b.MaxHealth))projects++;colony.workerDemand+=projects*2;int remaining=Math.Max(0,colony.workforce-(projects>0?Math.Min(4,Math.Max(2,projects/4)):0));
                for(int priority=0;priority<4;priority++){int demand=0;foreach(var b in local.Buildings)if(Available(b,priority))demand+=b.definition.workers*b.level;int budget=Math.Min(remaining,demand),left=demand;foreach(var b in local.Buildings)if(Available(b,priority)){int required=b.definition.workers*b.level;int assigned=left==0?0:(int)((long)budget*required/left);b.WorkersAssigned=assigned;b.WorkforceEfficiency=(float)assigned/required;budget-=assigned;left-=required;remaining-=assigned;colony.employed+=assigned;}}
            }
            bool Available(RtsBuilding b,int priority)=>b.team==0&&b.Complete&&!b.paused&&!b.roadSuspended&&b.powered&&b.definition.workers>0&&(b.node<0||local.Nodes[b.node].remaining>0)&&Priority(b.definition)==priority;
            int Priority(BuildingDefinition d){if(d.extractedResource=="water"||d.id.StartsWith("civil_farm_")||d.id=="civil_food_processing"||d.id=="civil_hydroponics"||d.id=="civil_beef_shed"||d.id=="civil_butcher")return 0;if(d.id==CivilisationRuntime.PoliceHeadquarters||d.id==CivilisationRuntime.Graveyard||d.extraction>0||CivilisationRuntime.Backbone(d))return 1;return d.id.StartsWith("civil_")?2:3;}
        }
        IEnumerator Scenario(bool streaming,PlanetConstructionGrid grid,PlanetSurface surface,List<RoadTile> tiles){
            var meshes=new Dictionary<int,Mesh>();var result=new Result{scheduler=streaming?"streamed":"combined",roads=tiles.Count,plots=1000,frames=1600,firstVisibleFrame=-1,finishedFrame=-1};var timer=Stopwatch.StartNew();double previous=timer.Elapsed.TotalMilliseconds;var samples=new List<double>();var geometrySamples=new List<double>();bool geometryWork=false;int frame=0;
            var builder=Build();bool active=true;for(frame=0;frame<result.frames;frame++){geometryWork=false;double beforeWork=timer.Elapsed.TotalMilliseconds;if(active){if(streaming)active=SettlementRoadRenderer.Advance(builder,.75);else active=builder.MoveNext();if(!active)result.finishedFrame=frame;}if(geometryWork)geometrySamples.Add(timer.Elapsed.TotalMilliseconds-beforeWork);if(result.firstVisibleFrame<0&&meshes.Count>0){result.firstVisibleFrame=frame;result.firstVisibleMs=timer.Elapsed.TotalMilliseconds;}yield return null;double now=timer.Elapsed.TotalMilliseconds;samples.Add(now-previous);previous=now;}
            Check(!active,"Road build finishes: "+result.scheduler);samples.Sort();result.medianMs=samples[samples.Count/2];result.p95Ms=samples[(int)Math.Ceiling(samples.Count*.95)-1];result.updatesPerSecond=result.frames/timer.Elapsed.TotalSeconds;result.maximumFrameMs=samples[samples.Count-1];geometrySamples.Sort();result.geometryMedianMs=geometrySamples[geometrySamples.Count/2];result.geometryP95Ms=geometrySamples[(int)Math.Ceiling(geometrySamples.Count*.95)-1];foreach(var mesh in meshes.Values){for(int stream=0;stream<mesh.vertexBufferCount;stream++)result.meshBufferBytes+=(long)mesh.vertexCount*mesh.GetVertexBufferStride(stream);result.meshBufferBytes+=(long)mesh.GetIndexCount(0)*4;}result.allocatedBytes=Profiler.GetTotalAllocatedMemoryLong();result.reservedBytes=Profiler.GetTotalReservedMemoryLong();GetProcessMemoryInfo(GetCurrentProcess(),out var memory,(uint)Marshal.SizeOf<Memory>());result.workingSetBytes=(long)memory.workingSet.ToUInt64();result.privateBytes=(long)memory.privateBytes.ToUInt64();report.results.Add(result);foreach(var mesh in meshes.Values)Destroy(mesh);yield return null;
            IEnumerator Build(){var vertices=new List<Vector3>();var normals=new List<Vector3>();var lows=new List<Vector3>();var uv=new List<Vector4>();var metrics=new List<Vector2>();var colours=new List<Color>();var indices=new List<int>();int chunk=0;
                for(int i=0;i<tiles.Count;i++){geometryWork=true;SettlementRoadRenderer.Append(grid,surface,tiles[i],false,vertices,normals,lows,uv,metrics,colours,indices);if(streaming){if((i+1)%128==32)Publish(chunk);if((i+1)%128==0){Publish(chunk++);vertices.Clear();normals.Clear();lows.Clear();uv.Clear();metrics.Clear();colours.Clear();indices.Clear();}yield return null;}else if((i+1)%16==0)yield return null;}
                if(!streaming){for(int i=0;i<1000;i++)yield return null;Publish(0);}
                void Publish(int slot){geometryWork=true;var mesh=SettlementRoadRenderer.Upload("Validation road",vertices,normals,lows,uv,metrics,colours,indices);if(meshes.TryGetValue(slot,out var old))Destroy(old);meshes[slot]=mesh;}
            }
        }
    }
